test('independent source-layout answers recover split names, ranks and exact dates', () => {
  const result = mapLegacyBook({ sheets: fixtures(), asOfDateNY: '2026-09-13' });
  for (const [sheet, row, name, marks, markType, date, evidence] of expected) {
    const c = result.candidates.find(item => item.sheetName === sheet && item.sourceRow === row);
    assert.equal(c.displayName, name, `${sheet} row ${row} name`);
    assert.equal(c.currentRank.known, true, name);
    assert.deepEqual([c.currentRank.belt, c.currentRank.marks, c.currentRank.markType], [sheet, marks, markType], name);
    assert.equal(c.currentRank.date.value, date, name);
    assert.equal(c.currentRank.date.known, Boolean(date), name);
    assert.ok(c.currentRank.evidenceRefs.includes(evidence), `${name} evidence`);
  }
});

test('known source name survives missing rank, summary conflicts, and archive uncertainty', () => {
  const result = mapLegacyBook({ sheets: fixtures(), asOfDateNY: '2026-09-13' });
  const unknown = ['TEST Prior Only', 'TEST Conflict Summary', 'TEST Brown Unknown', 'TEST Brown Chronology', 'TEST Purple Note', 'TEST Blue Conflict', 'TEST Blue Bare Belt', 'TEST Blue Future', 'TEST White Unknown', 'TEST White Blank'];
  for (const name of unknown) {
    const c = result.candidates.find(item => item.displayName === name);
    assert.ok(c, name);
    assert.deepEqual([c.currentRank.known, c.currentRank.marks], [false, null], name);
  }
  assert.equal(result.candidates.find(c => c.sheetName === 'Former student').displayName, 'TEST Archived Surname');
  assert.ok(result.candidates.filter(c => c.status === 'archived').every(c => !c.currentRank.known));
});

test('uncertain and annotated source dates remain distinct from missing dates', () => {
  const result = mapLegacyBook({ sheets: fixtures() });
  const rank = name => result.candidates.find(c => c.displayName === name).currentRank;
  assert.equal(rank('TEST Partial Date').date.precision, 'month');
  assert.equal(rank('TEST Purple Approximate').date.precision, 'approximate');
  assert.equal(rank('TEST Purple Question').date.precision, 'uncertain');
  assert.equal(rank('TEST White Multi Date').date.reason, 'multiple_dates_require_resolution');
  assert.equal(rank('TEST White Short Year').date.reason, 'two_digit_year_requires_resolution');
  assert.equal(rank('TEST White Annotation').date.reason, 'annotated_date_requires_resolution');
  assert.equal(rank('TEST White Invalid Date').date.reason, 'invalid_calendar_date');
  assert.equal(rank('TEST White Zero').date.precision, 'missing');
});

test('name repair preserves reviewed IDs, exact source values, and genuine duplicates', () => {
  const sheets = fixtures();
  const before = structuredClone(sheets);
  const first = mapLegacyBook({ sheets });
  const registry = first.candidates.slice(0, 2).map((c, i) => createLegacyBinding(c, { studentId: `TEST-EXISTING-${i}`, distinguishingLabel: `Legacy Black Belt row ${i + 2}` }));
  const second = mapLegacyBook({ sheets, registry });
  assert.deepEqual(sheets, before);
  assert.deepEqual(second.candidates.slice(0, 2).map(c => c.identity.studentId), ['TEST-EXISTING-0', 'TEST-EXISTING-1']);
  assert.deepEqual(second.candidates.slice(0, 2).map(c => c.displayName), ['TEST Avery Stone', 'TEST Avery River']);
  const repeated = second.candidates.filter(c => c.displayName === 'TEST Duplicate Full Name');
  assert.equal(repeated.length, 2);
  assert.notEqual(repeated[0].sourceFingerprint, repeated[1].sourceFingerprint);
  assert.deepEqual(second.candidates[2].items.slice(0, 2).map(i => i.value), ['TEST Élodie', 'D’Arcy-Smith']);
});

test('corrected interpretation keeps the exact pre-repair fingerprint and old registry binding', () => {
  // Fingerprint was captured from the original mapper before implementation.
  const sourceFingerprint = 'dbd671b00c257559b7abce19415278e42fa9cb6d8f7deee42bf920a3f318958d';
  const result = mapLegacyBook({
    sheets: [{ name: 'Black Belt', rows: [H.black, ['TEST Stable', 'Surname', '', '', '3/1/2024']] }],
    registry: [{ studentId: 'TEST-OLD-STUDENT-ID', distinguishingLabel: 'Legacy Black Belt row 2', sourceFingerprint, sourceRef: "'Black Belt'!A2:M2" }],
  });
  assert.equal(result.candidates[0].sourceFingerprint, sourceFingerprint);
  assert.equal(result.candidates[0].identity.studentId, 'TEST-OLD-STUDENT-ID');
  assert.equal(result.candidates[0].displayName, 'TEST Stable Surname');
  assert.equal(result.candidates[0].currentRank.marks, 4);
});

test('unsupported name layouts never concatenate B and arbitrary award text never counts as a stripe', () => {
  const sheets = fixtures();
  sheets[0].rows[0] = [...H.black];
  sheets[0].rows[0][1] = 'Other information';
  sheets[0].rows[1][1] = 'TEST unrelated detail';
  sheets[4].rows.push(['TEST Arbitrary', '', '', 'attended', '3 stripes?', 'joined 3/4/2024', '?']);
  const result = mapLegacyBook({ sheets });
  assert.equal(result.candidates[0].displayName, 'TEST Avery');
  assert.equal(result.candidates.find(c => c.displayName === 'TEST Arbitrary').currentRank.known, false);
});

test('documented mixed Black rows retain a complete A name when B is a Belt marker', () => {
  const sheets = [{ name: 'Black Belt', rows: [H.black,
    ['TEST Morgan Complete', 'Belt', '', '', '', '', '', '3/4/2024', '1/2/2021'],
    ['TEST Élodie', 'Du Pré', '', '', '4/5/2025'],
    ['TEST Cameron Complete', '', '', '', '', '', '', '', '6/7/2024'],
  ] }];
  const result = mapLegacyBook({ sheets }).candidates;
  assert.deepEqual(result.map(c => c.displayName), ['TEST Morgan Complete', 'TEST Élodie Du Pré', 'TEST Cameron Complete']);
  assert.deepEqual(result.map(c => c.currentRank.marks), [1, 4, 0]);
  assert.equal(result[0].nameEvidence.interpretation, 'complete_black_name_with_b_rank_marker');
  assert.equal(result[0].items[1].value, 'Belt');
});

test('a generic Belt summary neither forces zero nor contradicts a labeled positive stripe award', () => {
  const result = mapLegacyBook({ sheets: [{ name: 'Blue Belt', rows: [H.blue,
    ['TEST Generic Belt', 'Belt', '', '', '', '3/4/2024', '1/2/2021'],
    ['TEST Bare Generic', 'Belt'],
  ] }] }).candidates;
  assert.equal(result[0].currentRank.known, true);
  assert.equal(result[0].currentRank.marks, 1);
  assert.equal(result[0].currentRank.date.value, '2024-03-04');
  assert.equal(result[1].currentRank.known, false);
});

test('uncertainty in older awards does not suppress a clearly later current award', () => {
  const result = mapLegacyBook({ sheets: [{ name: 'Brown Belt', rows: [H.brown,
    ['TEST Older History', '4 stripes', '3/4/2025', '1/2/2021', '1/2/2022'],
  ] }] }).candidates[0];
  assert.equal(result.currentRank.known, true);
  assert.equal(result.currentRank.marks, 4);
  assert.equal(result.currentRank.date.value, '2025-03-04');
  assert.equal(result.currentRank.historicalConflicts.length, 1);
});

test('an explicit dated Belt annotation identifies a belt award while Transplant preserves arrival-date uncertainty', () => {
  const result = mapLegacyBook({ sheets: [{ name: 'Blue Belt', rows: [H.blue,
    ['TEST Dated Belt', 'belt', '', '', '', '', '2/11/2018(Belt)'],
    ['TEST Dated Transplant', 'belt', '', '', '', '', '2/11/2018(Transplant)'],
  ] }] }).candidates;
  assert.deepEqual(result.map(c => c.currentRank.marks), [0, 0]);
  assert.equal(result[0].currentRank.date.value, '2018-02-11');
  assert.equal(result[0].currentRank.date.annotation, 'Belt');
  assert.equal(result[1].currentRank.date.value, '');
  assert.equal(result[1].currentRank.date.sourceText, '2/11/2018(Transplant)');
});
